en vreemd leven binnengaan zonder zelf aanwezig te zijn. Op verschillende plaatsen in de wereld ontstaan zo verbindingen tussen mensen die elkaar nauwelijks kennen. Samanta Schweblin onderzoekt wat deze mengeling van huisdier, camera en anonieme aanwezigheid kan oproepen: nieuwsgierigheid en nabijheid, maar ook afhankelijkheid en onverwacht gevaar.","work_id":987146008,"evidence":[{"note":"Retain existing Work3199 Kentukis / Samanta Schweblin and exact Dutch Duizend ogen 9789493169227 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-028.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p427537371"],"reference":"work:3199","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-028.json","sources":["https://openlibrary.org/works/OL20760166W","https://data.bibliotheken.nl/id/nbt/p427537371"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789493169227","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":14860945,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL58496773M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","so